describe('Sequential Async Checkout Flow', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should complete checkout with sequential async steps in correct order', () => {
    // Step 1: Fill shipping form
    cy.get('[data-testid="shipping-address-input"]').type('123 Main St');
    cy.get('[data-testid="city-input"]').type('Anytown');
    cy.get('[data-testid="zip-input"]').type('12345');
    cy.get('[data-testid="continue-button"]').click();

    // Step 2: Fill payment details
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="expiry-month-input"]').type('12');
    cy.get('[data-testid="expiry-year-input"]').type('25');
    cy.get('[data-testid="cvv-input"]').type('123');
    cy.get('[data-testid="continue-button"]').click();

    // Step 3: Review and place order
    cy.get('[data-testid="order-summary"]').should('be.visible');
    cy.get('[data-testid="place-order-button"]').click();

    // Step 4: Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Order placed successfully');
    cy.get('[data-testid="order-confirmation-number"]').should('be.visible');
    cy.get('[data-testid="order-confirmation-number"]').should('have.length.greaterThan', 0);
  });

  it('should handle async step failure and prevent order placement', () => {
    // Step 1: Fill shipping form
    cy.get('[data-testid="shipping-address-input"]').type('123 Main St');
    cy.get('[data-testid="city-input"]').type('Anytown');
    cy.get('[data-testid="zip-input"]').type('12345');
    cy.get('[data-testid="continue-button"]').click();

    // Step 2: Fill payment details with invalid card
    cy.get('[data-testid="card-number-input"]').type('111');
    cy.get('[data-testid="expiry-month-input"]').type('12');
    cy.get('[data-testid="expiry-year-input"]').type('25');
    cy.get('[data-testid="cvv-input"]').type('123');
    cy.get('[data-testid="continue-button"]').click();

    // Step 3: Verify error message and prevent proceeding
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid card number');
    cy.get('[data-testid="place-order-button"]').should('be.disabled');

    // Step 4: Verify user is still on payment step
    cy.get('[data-testid="payment-step-header"]').should('be.visible');
    cy.get('[data-testid="order-summary"]').should('not.exist');
  });
});
